"""Cross-check browser-generated bytes with the independent Python decoder."""
from pathlib import Path
import shutil
import subprocess
import unittest

ROOT = Path(__file__).resolve().parents[1]
from project_decoder import inspect_project


@unittest.skipUnless(shutil.which("node"), "Node.js required for browser codec cross-check")
class BrowserEditorTests(unittest.TestCase):
    def run_codec(self, code):
        result = subprocess.run(["node", "-e", code], cwd=ROOT, check=True,
                                capture_output=True, text=True, timeout=30)
        return bytes.fromhex(result.stdout.strip())

    def test_created_project_decodes_independently(self):
        data = self.run_codec("""
const F=require('./project-editor/project-format.js');
const p=F.Project.create('Editor validation');
p.bpm=98.5;
p.addPattern(0,0);
p.setPattern(0,0,'pages',2);
p.setNote(0,0,0,0,{enabled:true,pitch:60,velocity:100,gate:7});
p.setNote(0,0,0,1,{enabled:true,pitch:64,velocity:91,gate:14});
p.setCC(0,0,0,2,64,true);
p.setTrack(0,'channel',2);
console.log(Buffer.from(p.serialize()).toString('hex'));
""")
        parsed = inspect_project(data)
        self.assertEqual((parsed["pattern_count"], parsed["bpm_x10"]), (1, 985))
        self.assertEqual(parsed["patterns"][0]["nominal_steps"], 32)
        notes = parsed["patterns"][0]["steps"][0]["notes"]
        self.assertEqual([(n["pitch"], n["velocity"], n["gate_raw"]) for n in notes],
                         [(60, 100, 7), (64, 91, 14)])
        self.assertEqual(parsed["patterns"][0]["steps"][0]["cc_mask"], 4)
        self.assertEqual(parsed["patterns"][0]["steps"][0]["cc_values"][2], 64)
        self.assertTrue(all(t["track_setting_version"] == 3 for t in parsed["tracks"]))
        self.assertEqual(parsed["tracks"][0]["routing_v3"],
                         dict(port_code=3, port="USB", midi_channel=2))

    def test_edited_synthetic_project_keeps_every_unrelated_byte(self):
        data = self.run_codec("""
const F=require('./project-editor/project-format.js');
const p=F.Project.parse(require('./tests/project-fixtures.cjs').fixture);
p.setNote(0,0,0,0,{pitch:61});
console.log(Buffer.from(p.serialize()).toString('hex'));
""")
        original = self.run_codec("console.log(require('./tests/project-fixtures.cjs').fixture.toString('hex'))")
        self.assertEqual([i for i, (a, b) in enumerate(zip(original, data)) if a != b],
                         [4096 + 0x290])
        parsed = inspect_project(data)
        self.assertEqual(parsed["patterns"][0]["steps"][0]["notes"][0]["pitch"], 61)

    def test_original_editor_example_decodes_independently(self):
        code = "const p=require('./project-editor/example-project.js').create(); console.log(Buffer.from(p.serialize()).toString('hex'));"
        data = self.run_codec(code)
        self.assertEqual(data, self.run_codec(code))
        parsed = inspect_project(data)
        self.assertEqual(parsed["project_name"], "Editor example")
        self.assertEqual(parsed["pattern_count"], 6)
        self.assertEqual(parsed["bpm_x10"], 1200)
        self.assertEqual([p["track"] for p in parsed["patterns"]], [1, 1, 2, 2, 9, 9])
        notes = parsed["patterns"][4]["steps"]
        self.assertEqual([(step["step"], note["pitch"]) for step in notes for note in step["notes"]],
                         [(0, 48), (4, 55), (8, 52), (12, 57)])


if __name__ == "__main__":
    unittest.main()
